/**
 * SpendPilot AI Conversation Turn Diagnostics (Section 12)
 *
 * Lightweight development-only diagnostics tracking for each conversation turn:
 * - Request ID
 * - Session revision
 * - Actual model ID
 * - API method
 * - SDK version
 * - Whether system instructions were provided
 * - Number of relevant conversation turns supplied
 * - Whether current workspace state was included
 * - Gemini response structure / finish reason
 * - Parsed action
 * - Whether clarification was generated by Gemini
 * - Number of generated options
 * - Whether any application fallback modified the response
 * - Whether Channel3 was called and why
 *
 * Privacy Notice: No API keys, access tokens, or sensitive personal information are ever logged.
 */

export interface ConversationTurnDiagnosticEntry {
  requestId: string;
  sessionRevision: number;
  timestamp: number;
  modelId: string;
  apiMethod: "generateContent" | "generateContentStream" | "interactions" | "deterministic-fallback";
  sdkVersion: string;
  hasSystemInstruction: boolean;
  conversationTurnsCount: number;
  hasWorkspaceState: boolean;
  parsedAction: string;
  isClarification: boolean;
  optionsCount: number;
  usedFallback: boolean;
  channel3Called: boolean;
  channel3Reason?: string;
  finishReason?: string;
  error?: string;
  workspaceId?: string;
  itemId?: string;
  submissionId?: string;
  searchId?: string;
  operationId?: string;
  cartMutationId?: string;
  actualApiCallCount?: number;
}

// In-memory circular buffer of recent turn diagnostics (capped at 50 for development)
const RECENT_DIAGNOSTICS: ConversationTurnDiagnosticEntry[] = [];
const MAX_DIAGNOSTICS_HISTORY = 50;

/**
 * Records a turn diagnostic entry in development mode.
 */
export function logConversationTurnDiagnostics(entry: ConversationTurnDiagnosticEntry): void {
  RECENT_DIAGNOSTICS.push(entry);
  if (RECENT_DIAGNOSTICS.length > MAX_DIAGNOSTICS_HISTORY) {
    RECENT_DIAGNOSTICS.shift();
  }

  if (process.env.NODE_ENV !== "production") {
    const summary = [
      `[SpendPilot Turn Diagnostics]`,
      `req=${entry.requestId}`,
      `rev=${entry.sessionRevision}`,
      `model=${entry.modelId}`,
      `method=${entry.apiMethod}`,
      `sdk=${entry.sdkVersion}`,
      `sysInst=${entry.hasSystemInstruction}`,
      `turns=${entry.conversationTurnsCount}`,
      `workspace=${entry.hasWorkspaceState}`,
      `action=${entry.parsedAction}`,
      `clarification=${entry.isClarification}`,
      `optionsCount=${entry.optionsCount}`,
      `fallback=${entry.usedFallback}`,
      `ch3Called=${entry.channel3Called}`,
      entry.workspaceId ? `workspaceId=${entry.workspaceId}` : null,
      entry.itemId ? `itemId=${entry.itemId}` : null,
      entry.submissionId ? `submissionId=${entry.submissionId}` : null,
      entry.searchId ? `searchId=${entry.searchId}` : null,
      entry.operationId ? `operationId=${entry.operationId}` : null,
      entry.cartMutationId ? `cartMutationId=${entry.cartMutationId}` : null,
      entry.actualApiCallCount !== undefined ? `apiCalls=${entry.actualApiCallCount}` : null,
      entry.channel3Reason ? `ch3Reason="${entry.channel3Reason}"` : null,
      entry.error ? `err="${entry.error}"` : null,
    ]
      .filter(Boolean)
      .join(" ");

    // Safe development console logging (no PII, no secrets)
    console.info(summary);
  }
}

/**
 * Retrieves the recent diagnostic entries (for development inspection & test verification).
 */
export function getRecentTurnDiagnostics(limit?: number): ReadonlyArray<ConversationTurnDiagnosticEntry> {
  if (typeof limit === "number" && limit > 0) {
    return RECENT_DIAGNOSTICS.slice(-limit);
  }
  return [...RECENT_DIAGNOSTICS];
}

/**
 * Clears diagnostics history (useful between test runs).
 */
export function clearTurnDiagnostics(): void {
  RECENT_DIAGNOSTICS.length = 0;
}
